from pathlib import Path
import datetime as _dt
import re


EXPECTED_ROW = [
    ("Case ID", "LC-2026-0089"),
    ("Employee ID", "E1051"),
    ("Employee Name", "Rosa Gutierrez"),
    ("Leave Type(s)", "FMLA + FAMLI"),
    ("Start Date", "2026-02-02"),
