    (
        "Notes",
        "Certified for recurring migraines; up to 2 days/month. Freq: up to 2x/mo; "
        "duration: 1 day per episode. Cert expires 08/01/2026.",
    ),
]
NOTES_INDEX = 14


def _norm_cell(value):
    if value is None:
        return ""
    if isinstance(value, bool):
        return str(value).lower()
    if isinstance(value, _dt.datetime):
        if (value.hour, value.minute, value.second, value.microsecond) == (0, 0, 0, 0):
            return value.strftime("%Y-%m-%d")
        return value.strftime("%Y-%m-%d %H:%M:%S")
    if isinstance(value, _dt.date):
        return value.strftime("%Y-%m-%d")
    if isinstance(value, (int, float)):
        try:
            if float(value) == int(value):
                return str(int(value))
        except (ValueError, OverflowError):
            pass
        return str(value)

    text = " ".join(str(value).split())
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
        try:
            parsed = _dt.datetime.strptime(text, fmt)
        except ValueError:
            continue
        if (parsed.hour, parsed.minute, parsed.second) == (0, 0, 0):
            return parsed.strftime("%Y-%m-%d")
        return parsed.strftime("%Y-%m-%d %H:%M:%S")
    try:
        number = float(text)
        if number == int(number):
            return str(int(number))
    except (ValueError, OverflowError):
        pass
    return text


def _short(text):
    return text if len(text) <= 120 else text[:117] + "..."


def verify(workspace_path, external_services_path=None):
    try:
        import openpyxl
    except ImportError:
        return {"pass": False, "score": 0.0, "feedback": "openpyxl not available"}

    workspace = Path(workspace_path)
    xlsx_files = list(workspace.glob("*.xlsx")) + list(workspace.glob("*.xls"))
    if not xlsx_files:
        return {"pass": False, "score": 0.0, "feedback": "No Excel file found in workspace"}

    leave_tracker = next((f for f in xlsx_files if f.stem.lower() == "leave_tracker"), None)
    if leave_tracker is None:
        leave_tracker = next(
            (f for f in xlsx_files if f.stem.lower().startswith("leave_tracker")),
            None,
        )
    if leave_tracker is None:
        return {
            "pass": False,
            "score": 0.0,
            "feedback": (
                "leave_tracker.xlsx not found in workspace. "
                f"Files present: {[f.name for f in xlsx_files]}"
            ),
        }

    try:
        wb = openpyxl.load_workbook(leave_tracker, data_only=True)
    except Exception as exc:
        return {
            "pass": False,
            "score": 0.0,
            "feedback": f"Could not open {leave_tracker.name}: {exc}",
        }

    ws = wb.active
    data_rows = []
    header_seen = False
    for row in ws.iter_rows(values_only=True):
        if all(cell is None for cell in row):
            continue
        if not header_seen:
            header_seen = True
            continue
        data_rows.append(row)

    if len(data_rows) != 47:
        return {
            "pass": False,
            "score": 0.5,
            "feedback": f"Expected 47 cases in {leave_tracker.name}, found {len(data_rows)}",
        }

    case_rows = [
        row
        for row in data_rows
        if row and _norm_cell(row[0]).lower() == "lc-2026-0089"
    ]
    if len(case_rows) != 1:
        return {
            "pass": False,
            "score": 0.5,
            "feedback": (
                "Expected exactly one LC-2026-0089 row in leave_tracker, "
                f"found {len(case_rows)}"
            ),
        }

    raw_cells = list(case_rows[0])
    if len(raw_cells) < len(EXPECTED_ROW):
        raw_cells += [None] * (len(EXPECTED_ROW) - len(raw_cells))

    mismatches = []
    for index, (column_name, expected_value) in enumerate(EXPECTED_ROW):
        if index == NOTES_INDEX:
            continue
        actual_value = _norm_cell(raw_cells[index])
        if actual_value != expected_value:
            mismatches.append(
                f"{column_name}: expected {_short(expected_value)!r}, "
                f"found {_short(actual_value)!r}"
            )
    for index in range(len(EXPECTED_ROW), len(raw_cells)):
        extra_value = _norm_cell(raw_cells[index])
        if extra_value:
            mismatches.append(
                f"unexpected extra cell (column {index + 1}): {_short(extra_value)!r}"
            )
    if mismatches:
        return {
            "pass": False,
            "score": 0.5,
            "feedback": (
                "LC-2026-0089 seeded non-Notes fields must remain unchanged; "
                f"changed cell(s): {'; '.join(mismatches)}"
            ),
        }

    seeded_notes = EXPECTED_ROW[NOTES_INDEX][1]
    actual_notes = _norm_cell(raw_cells[NOTES_INDEX])
    note_issues = []
    if not actual_notes.startswith(seeded_notes):
        note_issues.append("seeded Notes content was removed or changed")
        continuation = ""
    else:
        continuation = actual_notes[len(seeded_notes):].lstrip(" |;—-")
        if not continuation:
            note_issues.append("no new continuation entry was appended")

    continuation_lower = continuation.lower()
    requirements = [
        ("04/13/2026" in continuation, "continuation entry is not dated 04/13/2026"),
        (bool(re.search(r"\bpto\b", continuation_lower)), "continuation entry does not identify PTO"),
        (bool(re.search(r"\bfamli\b", continuation_lower)), "continuation entry does not identify FAMLI"),
        (bool(re.search(r"\b(question|asked|asks|inquir(?:y|ed))\b", continuation_lower)), "continuation entry does not record the employee's question"),
        ("payroll" in continuation_lower, "continuation entry does not identify the payroll handoff"),
        (
            bool(
                re.search(
                    r"\b(relay(?:ed)?|rout(?:e|ed)|refer(?:red)?|hand(?:ed)?\s*off|handoff|post(?:ed)?)\b",
                    continuation_lower,
                )
            ),
            "continuation entry does not record that the question was handed off",
        ),
    ]
    note_issues.extend(message for passed, message in requirements if not passed)
    if note_issues:
        return {
            "pass": False,
            "score": 0.5,
            "feedback": f"LC-2026-0089 Notes issues: {'; '.join(note_issues)}",
        }

    bereavement_rosa_cases = []
    for row in data_rows:
        row_text = " ".join(_norm_cell(cell).lower() for cell in row)
        if (
            "rosa gutierrez" in row_text
            and "bereavement" in row_text
            and _norm_cell(row[0]).lower() != "lc-2026-0089"
        ):
            bereavement_rosa_cases.append(row)
    if bereavement_rosa_cases:
        return {
            "pass": False,
            "score": 0.0,
            "feedback": (
                f"Found {len(bereavement_rosa_cases)} unexpected bereavement "
                "case(s) for Rosa Gutierrez"
            ),
        }

    return {
        "pass": True,
        "score": 1.0,
        "feedback": (
            f"{leave_tracker.name} has exactly 47 cases and exactly one LC-2026-0089 row; "
            "all seeded non-Notes fields and prior Notes content are preserved; a dated "
            "PTO/FAMLI payroll-question handoff entry was appended; no new bereavement "
            "case exists for Rosa Gutierrez"
        ),
    }

