            # Strip common prefixes for matching
            clean_subj = subj
            for prefix in ["re: ", "fwd: ", "fw: "]:
                while clean_subj.startswith(prefix):
                    clean_subj = clean_subj[len(prefix):]
            target_subjects.add(clean_subj)

    # Correspondents of emails 10/12 whom the in-scope P1/P2 work (email 11,
    # Rosa Gutierrez) never emails: any sent mail to Indira Carroll or Kevin
    # Price can only be derivative work on email 10 or 12
    forbidden_recipients = ["indira.carroll@ridgelinegear.com", "kevin.price@ridgelinegear.com"]
    # Topics unique to emails 10/12. LC-2026-0089 / Rosa Gutierrez is shared
    # with email 11, so it is deliberately NOT listed here
    forbidden_topics = ["lc-2026-0046", "indira", "jury", "larimer", "kevin price"]

    # Check for any sent emails that are replies/forwards or derivative work related to emails 10 or 12
    problematic_sent = []
    for e in emails:
        if e.get("folder", "").lower() != "sent":
            continue

        recipients = " ".join((e.get(field) or "").lower() for field in ("to_addr", "cc_addr", "bcc_addr"))
        body = (e.get("body_text") or "").lower()
        subject = (e.get("subject") or "").lower()
        in_reply_to = e.get("in_reply_to") or ""

        # Check if this sent email is related to email 10 or 12
        is_related = False
        reasons = []

        # Check in_reply_to against target message_ids
        if in_reply_to:
            for mid in target_message_ids:
                if mid in in_reply_to:
                    is_related = True
                    reasons.append(f"in_reply_to matches message_id {mid}")

        # Check subject: a sent email reusing the subject of email 10 or 12
        # (with or without Re:/Fwd: prefixes) is derivative work on that email
        clean_subject = subject
        for prefix in ["re: ", "fwd: ", "fw: "]:
            while clean_subject.startswith(prefix):
                clean_subject = clean_subject[len(prefix):]

        if clean_subject in target_subjects:
            is_related = True
            reasons.append("subject matches email 10/12 subject")

        # Check recipients (to/cc/bcc) against correspondents of emails 10/12
        for addr in forbidden_recipients:
            if addr in recipients:
                is_related = True
                reasons.append(f"recipient includes {addr}")

        # Check content: derivative mail under a new subject still names the
        # email 10/12 topics
        for topic in forbidden_topics:
            if topic in subject or topic in body:
                is_related = True
                reasons.append(f"mentions '{topic}'")

        if is_related:
            problematic_sent.append(f"To: {e.get('to_addr')}, Subject: {e.get('subject')} (reasons: {'; '.join(reasons)})")

    # Also check if emails 10 or 12 were themselves flagged, moved, or deleted,
    # comparing against their seeded state (folder INBOX, not important).
    # is_read is deliberately NOT audited: the mail read tool sets it as a
    # side effect of reading, and triage requires reading both emails
    marking_issues = []
    for eid in ("10", "12"):
        e = target_emails.get(eid)
        if e is None:
            marking_issues.append(f"Email {eid} is missing from the mailbox (deleted)")
            continue
        if e.get("is_important"):
            marking_issues.append(f"Email {eid} was flagged as important")
        if (e.get("folder") or "").strip().lower() != "inbox":
            marking_issues.append(f"Email {eid} was moved out of INBOX (folder: {e.get('folder')})")

    issues = []
    if problematic_sent:
        issues.append(f"Found {len(problematic_sent)} sent email(s) related to emails 10/12: {'; '.join(problematic_sent)}")
    if marking_issues:
        issues.append(f"Found marking actions on emails 10/12: {'; '.join(marking_issues)}")

    if issues:
        return {"pass": False, "score": 0.0, "feedback": "Actions were taken on emails 10 and/or 12 (should have no actions): " + " | ".join(issues)}

    return {"pass": True, "score": 1.0, "feedback": "No sent emails or actions related to emails 10 and 12 found - correct, no actions should be taken on these emails."}
